// Run after changing the canonical animation manifest. No npm dependencies.
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
const text = fs.readFileSync(path.join(root, "web/assets/animations/manifest.json"), "utf8");
JSON.parse(text);
fs.writeFileSync(path.join(root, "web/animation-data.js"),
  "// Generated by tools/sync-animation-data.cjs; edit assets/animations/manifest.json.\n" +
  "globalThis.HeroAnimationData = " + text.trim() + ";\n");
fs.mkdirSync(path.join(root, "unity/Assets/Resources/Art/Animations"), { recursive: true });
fs.writeFileSync(path.join(root, "unity/Assets/Resources/Art/Animations/manifest.json"), text);
console.log("Browser and Unity animation data synchronized.");
